import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { buildSync, version } from 'esbuild';

const artifact = 'supabase/functions/_shared/post-approval-report.bundle.js';
const manifestPath = 'supabase/functions/post-approval-report.bundle-manifest.json';
const normalized = path => readFileSync(path, 'utf8').replace(/\r\n?/g, '\n');
const digest = value => createHash('sha256').update(value).digest('hex');

/** Generated runtime code only. Original Deno/Node type and behavioral checks remain required. */
export function generateReportBundle({ check = false, assetsOnly = false } = {}) {
  const lock = JSON.parse(normalized('package-lock.json'));
  const pkg = JSON.parse(normalized('package.json'));
  if (version !== '0.28.2' || pkg.devDependencies.esbuild !== version ||
      lock.packages[''].devDependencies.esbuild !== version ||
      lock.packages['node_modules/esbuild'].version !== version ||
      pkg.dependencies.zod !== '4.4.3' || lock.packages['node_modules/zod'].version !== '4.4.3' ||
      JSON.parse(normalized('node_modules/zod/package.json')).version !== '4.4.3') {
    throw new Error('Report bundle dependency version drift');
  }
  for (const name of ['esbuild', 'zod']) {
    const entry = lock.packages[`node_modules/${name}`];
    if (!entry.integrity?.startsWith('sha512-') || !entry.resolved?.startsWith('https://registry.npmjs.org/')) {
      throw new Error('Report bundle dependency integrity metadata missing');
    }
  }
  const notice = normalized('node_modules/zod/LICENSE').trim();
  if (!notice.startsWith('MIT License') || notice.includes('*/')) throw new Error('Report license source drift');
  const built = buildSync({
    stdin: {
      contents: [
        'export { createSupabasePostApprovalReportEdgeHandler } from "./post-approval-report-runtime.ts";',
        'export { createSupabasePostApprovalModuleEdgeHandler } from "./post-approval-module-runtime.ts";',
        'export { createPostApprovalEvidenceEdgeHandler } from "./post-approval-evidence-api.ts";',
        'export { createPostApprovalReportEdgeHandler } from "./post-approval-report-api.ts";',
        'export { SupabasePostApprovalRoomIssueService } from "./post-approval-report-service.ts";',
        'export { AppError } from "./post-approval-report-error.ts";',
        'export { requestHash } from "./post-approval-report-command.ts";'
      ].join('\n'),
      resolveDir: resolve('supabase/functions/_shared'), loader: 'ts'
    },
    bundle: true, write: false, format: 'esm', platform: 'neutral', target: 'es2022',
    alias: { 'npm:zod@4.4.3': 'zod' }, external: ['./runtime.ts', './photo-binary.ts', 'node:buffer', 'node:crypto'],
    metafile: true, legalComments: 'inline', minify: false,
    banner: { js: `// Generated by scripts/generate-post-approval-report-bundle.mjs. DO NOT EDIT.\n/* zod 4.4.3\n${notice}\n*/` }
  });
  const code = built.outputFiles[0].text;
  const externals = [...new Set(Object.values(built.metafile.outputs).flatMap(output => output.imports).map(item => item.path))].sort();
  if (JSON.stringify(externals) !== JSON.stringify(['./photo-binary.ts', './runtime.ts', 'node:buffer', 'node:crypto'])) {
    throw new Error('Report bundle external graph drift');
  }
  const inputs = Object.keys(built.metafile.inputs).filter(path => path !== '<stdin>');
  inputs.push('scripts/generate-post-approval-report-bundle.mjs', 'scripts/generate-post-approval-report-edge.mjs',
    'package.json', 'package-lock.json', 'node_modules/zod/LICENSE', 'node_modules/esbuild/lib/main.js',
    'supabase/functions/_shared/runtime.ts', 'src/modules/auth/auth-context.ts', 'src/domain/actor.ts', 'src/lib/app-error.ts', 'src/lib/command.ts',
    'src/modules/post-approval-room-issues/post-approval-room-issue-contract.ts',
    'src/modules/post-approval-room-issues/post-approval-room-issue.service.ts',
    'src/modules/post-approval-room-issues/post-approval-room-issue.routes.ts');
  inputs.push('supabase/functions/_shared/photo-binary.ts',
    'src/modules/post-approval-room-issues/post-approval-room-issue-evidence.service.ts',
    'src/modules/post-approval-room-issues/post-approval-room-issue-handover.service.ts',
    'src/modules/post-approval-room-issues/post-approval-room-issue-upload-contract.ts',
    'src/modules/post-approval-room-issues/post-approval-room-issue-handover-contract.ts',
    'src/modules/post-approval-room-issues/post-approval-room-issue-evidence.routes.ts');
  const hashes = Object.fromEntries([...new Set(inputs)].sort().map(path => [path.replaceAll('\\', '/'), digest(normalized(path))]));
  const manifest = JSON.stringify({
    schemaVersion: 1, esbuild: version, zod: '4.4.3', externals,
    packages: Object.fromEntries(['esbuild', 'zod'].map(name => [name, {
      version: lock.packages[`node_modules/${name}`].version,
      integrity: lock.packages[`node_modules/${name}`].integrity
    }])),
    inputs: hashes, artifact, bytes: Buffer.byteLength(code), sha256: digest(code)
  }, null, 2) + '\n';
  if (assetsOnly) {
    if (normalized(manifestPath) !== manifest) throw new Error('Report reviewed manifest drift');
    writeFileSync(artifact, code);
  } else if (check) {
    if (normalized(artifact) !== code || normalized(manifestPath) !== manifest) {
      throw new Error('Report generated bundle/manifest drift: regenerate from reviewed source');
    }
  } else {
    writeFileSync(artifact, code);
    writeFileSync(manifestPath, manifest);
  }
  console.log(`Report generated bundle ${check ? 'verified' : 'generated'}: ${Buffer.byteLength(code)} bytes`);
  return { artifact, manifest: JSON.parse(manifest) };
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  generateReportBundle({ check: process.argv.includes('--check'), assetsOnly: process.argv.includes('--assets-only') });
}
